import { BadRequestException } from '@nestjs/common';
import type { WorkflowDslV2Field, WorkflowDslV2Output } from './temporal-workflow.types';

/**
 * Compiler-generated Result Builder (design doc §8.3).
 *
 * When `workflowDsl.v2Output.fields` is declared, the workflow's
 * `_build_workflow_result(step_results)` is generated by the compiler instead of
 * being left to free-form AI code: each output field is extracted from its
 * declared source step + JSON path, optional expressions (`length`) are applied,
 * and required fields get pre-execution assertions that raise ApplicationError
 * when the source path is missing at runtime.
 *
 * The generated builder takes `step_results: Dict[str, Any]` keyed by step id,
 * so the same builder shape works for every deterministic workflow layout
 * (single activity, http+transform pipeline, browser phase list).
 *
 * Unresolvable fields (source step not among `validStepIds`, or no source at
 * all) fail closed at compile time (§8.2 rules 2/3): the builder throws, so
 * codegen rejects the DSL instead of emitting a runtime fallback. Runtime
 * pre-execution assertions remain only for *resolvable* required fields.
 */
export function buildV2OutputResultBuilderLines(args: {
  v2Output: WorkflowDslV2Output;
  validStepIds: string[];
  resultType: string;
  title: string;
  preferAiSummary?: boolean;
}): string[] {
  const { v2Output, validStepIds, resultType, title, preferAiSummary = true } = args;
  const fields =
    v2Output?.fields && typeof v2Output.fields === 'object' && !Array.isArray(v2Output.fields)
      ? v2Output.fields
      : {};

  const assertLines: string[] = [];
  const fieldLines: string[] = [];

  for (const [fieldName, rawSpec] of Object.entries(fields)) {
    const spec: WorkflowDslV2Field =
      rawSpec && typeof rawSpec === 'object' ? rawSpec : ({} as WorkflowDslV2Field);
    const expressionKind = spec.source?.expression?.kind;
    // expression.source takes precedence over field.source (§8.1: length/identity
    // fields declare their own source inside the expression).
    const source = spec.source?.expression?.source ?? spec.source;
    const stepId = source?.step?.trim();
    const path = source?.path?.trim();
    const resolvable = Boolean(stepId && path && validStepIds.includes(stepId));

    if (!resolvable) {
      // §8.2 rule 2/3: unresolvable fields fail closed at compile time — the
      // compiler must reject the DSL rather than emit a runtime error path.
      if (!stepId || !path) {
        throw new BadRequestException(
          `workflowDsl.v2Output.${fieldName} 没有可解析的 source 或 expression（§8.2 rule 2: 需要 source.step 与 source.path）`
        );
      }
      throw new BadRequestException(
        `workflowDsl.v2Output.${fieldName} 的 source.step "${stepId}" 不存在于工作流步骤中（§8.2 rule 3）`
      );
    }
    const stepRef = `step_results.get(${JSON.stringify(stepId)})`;
    const extractExpr = `cls._extract_v2_path(${stepRef}, ${JSON.stringify(path)})`;
    if (spec.required) {
      assertLines.push(
        `        cls._assert_required_path(${stepRef}, ${JSON.stringify(path)}, ${JSON.stringify(fieldName)})`
      );
    }
    if (expressionKind === 'length') {
      fieldLines.push(
        `            ${JSON.stringify(fieldName)}: len(${extractExpr} or []),`
      );
    } else if (expressionKind === 'string_format') {
      // string_format: stringify the extracted source value (None → "None" 不会
      // 静默丢失；真正的格式串如 "%s-%s" 留给 expression 规范后续扩展)
      fieldLines.push(`            ${JSON.stringify(fieldName)}: str(${extractExpr}),`);
    } else {
      fieldLines.push(`            ${JSON.stringify(fieldName)}: ${extractExpr},`);
    }
  }

  return [
    '    @staticmethod',
    '    def _extract_v2_path(value: Any, path: str) -> Any:',
    '        current = value',
    '        raw_path = str(path or "").strip()',
    '        if raw_path.startswith("$."):',
    '            raw_path = raw_path[2:]',
    '        elif raw_path.startswith("$"):',
    '            raw_path = raw_path[1:]',
    '        segments = [item for item in raw_path.split(".") if item]',
    '        if not segments:',
    '            return current',
    '        for segment in segments:',
    '            clean_seg = segment.lstrip("$")',
    '            if isinstance(current, list) and clean_seg.isdigit():',
    '                index = int(clean_seg)',
    '                current = current[index] if 0 <= index < len(current) else None',
    '            elif isinstance(current, dict):',
    '                if segment in current:',
    '                    current = current[segment]',
    '                elif clean_seg in current:',
    '                    current = current[clean_seg]',
    '                elif clean_seg in ("result", "data", "body") and not any(k in current for k in ("result", "data", "body")):',
    '                    pass',
    '                else:',
    '                    return None',
    '            else:',
    '                return None',
    '        return current',
    '',
    '    @classmethod',
    '    def _assert_required_path(cls, step_result: Any, path: str, field_name: str) -> None:',
    '        extracted = cls._extract_v2_path(step_result, path)',
    '        if extracted is None or extracted == "" or extracted == [] or extracted == {}:',
    '            raise ApplicationError(f"缺少必填输出字段 \'{field_name}\'（路径 {path}）", non_retryable=True)',
    '',
    '    @classmethod',
    '    def _build_workflow_result(cls, step_results: Dict[str, Any]) -> Dict[str, Any]:',
    ...assertLines,
    '        business_data = {',
    ...fieldLines,
    '        }',
    '        summary = cls._extract_summary(business_data)',
    '        detail_text = cls._extract_detail_text(business_data)',
    '        return {',
    '            "execution": {',
    '                "status": "success",',
    '            },',
    '            "trigger": {',
    '                "type": "manual",',
    '            },',
    '            "result": {',
    `                "resultType": ${JSON.stringify(resultType)},`,
    `                "title": ${JSON.stringify(title)},`,
    '                "summary": summary,',
    '                "businessData": business_data,',
    '            },',
    '            "artifacts": cls._collect_artifacts(business_data),',
    '            "presentation": {',
    `                "preferAiSummary": ${preferAiSummary ? 'True' : 'False'},`,
    '                "preferStructuredView": False,',
    '                "chatSummary": summary,',
    '                "notificationSummary": summary,',
    '                "summaryFormat": "plain_text",',
    '                "detailText": detail_text,',
    '                "detailFormat": "plain_text",',
    '            },',
    '        }',
    '',
  ];
}

/**
 * True when the DSL declares at least one v2Output field (i.e. the compiler
 * must seal the result builder instead of passing the raw result through).
 */
export function hasV2OutputFields(v2Output: WorkflowDslV2Output | null | undefined): boolean {
  return Boolean(v2Output?.fields && Object.keys(v2Output.fields).length > 0);
}

/**
 * Python dict literal argument for `_build_workflow_result(...)` mapping each
 * source step id to the local Python variable holding that step's result.
 *
 * ```
 * {
 *     "step_1": normalized_result,
 * }
 * ```
 */
export function buildV2StepResultsArgument(stepToVar: Record<string, string>): string {
  const entries = Object.entries(stepToVar).map(
    ([stepId, varName]) => `            ${JSON.stringify(stepId)}: ${varName},`
  );
  return ['{', ...entries, '        }'].join('\n');
}
